# Find Minimum in Rotated Sorted Array
# Idea: The key idea is to perform binary search to find the minimum element in the rotated sorted array. We compare the middle element with its neighbors to determine if it is the minimum element. Depending on the comparison, w…
# Line comments below keep the same logic as the NeetCode 150 repo solution.

class Solution:
    def findMin(self, nums: List[int]) -> int:
        left, right = 0, len(nums) - 1

        while left < right:
            mid = left + (right - left) // 2

            if nums[mid] > nums[right]:
                left = mid + 1
            else:
                right = mid

        return nums[left]
